import numpy as np

# MECHANISM: Introduce a penalty for leftover gaps smaller than the smallest item to encourage better packing.

def priority(item, bins):
    smallest_item = 1  # Minimum item size
    penalty = np.where(bins - item < smallest_item, 0.5, 1)
    return np.array([penalty[i] * (150 - bins[i]) for i in range(len(bins))])

